Given a matrix mat of size n × n, construct a 2D linked list that represents the matrix, where each node stores the value of a cell and contains pointers to its right and down neighbors.Example:Input : mat = [[1 2 3]                         [4 5 6]                         [7 8 9]]Output : Input : mat = [[23 28]                         [23 28]]Output : Try It YourselfTable of ContentRecursive Approach - O(n^2) Time and O(n^2) SpaceIterative Approach - O(n^2) Time and O(n^2) SpaceRecursive Approach - O(n^2) Time and O(n^2) SpaceStart at the (0, 0) position of the given matrix and create a node for each matrix element. Each node’s right pointer links to the next element in the same row, while its down pointer connects to the element directly below in the columnFollow the steps below to solve the problem:Recursively do the following steps for any cell in the matrix:If the cell is out of bounds, return null.Create a new Node with the value from the matrix for the current cell.Recursively construct the right node for the next cell in the row.Recursively construct the down node for the next cell in the column.Finally return the root Node.
            C++

    #include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node *right, *down;

    Node(int x) {
        data = x;
        right = down = nullptr;
    }
};

// Function to recursively construct the linked matrix 
// from a given 2D vector
Node* constructUtil(vector<vector<int>>& mat, 
                                      int i, int j) {

    // Base case: if we are out of bounds, return NULL
    if (i >= mat.size() || j >= mat[0].size()) {
        return nullptr;
    }

    // Create a new Node with the current matrix value
    Node* curr = new Node(mat[i][j]);

    // Recursively construct the right and down pointers
    curr->right = constructUtil(mat, i, j + 1);
    curr->down = constructUtil(mat, i + 1, j);

    // Return the constructed Node
    return curr;
}

// Function to construct the linked matrix given a 2D vector
Node* constructLinkedMatrix(vector<vector<int>>& mat) {

    // Call the utility function starting 
    // from the top-left corner of the matrix
    return constructUtil(mat, 0, 0);
}

void printList(Node *head) {
    Node *currRow = head;
    while (currRow != nullptr) {
        Node *currCol = currRow;
        while (currCol != nullptr) {
            cout << currCol->data << " ";
            currCol = currCol->right;
        }
        cout << endl;
        currRow = currRow->down;
    }
}

int main() {


    vector<vector<int>> mat = { { 1, 2, 3 },
                                { 4, 5, 6 },
                                { 7, 8, 9 } };

    Node* head = constructLinkedMatrix(mat);
    printList(head);

    return 0;
}


