Iterative Approach - O(n^2) Time and O(n^2) SpaceThe approach involves creating m linked lists. Each node in these linked lists stores a reference to its right neighbor. The head pointers of each linked list are maintained in an array. After constructing the linked lists, we traverse through them and for each i-th and (i+1)-th list, we establish the down pointers of each node in i-th list to point to the corresponding node in (i+1)-th list.The idea is to create m linked lists (m = number of rows) whose each node stores its right node. The head pointers of each m linked lists are stored in an array of nodes.Then, traverse m lists, for every ith and (i+1)th list, set the down pointers of each node of ith list to its corresponding node of (i+1)th list.  
            C++

    // C++ to implement linked matrix 
// from a 2D matrix iteratively 
#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node *right, *down;

    Node(int x) {
        data = x;
        right = down = nullptr;
    }
};

// Function to construct the linked list from the given
/// matrix and return the head pointer
Node* constructLinkedMatrix(vector<vector<int>>& mat) {
    int m = mat.size();
    int n = mat[0].size();

    // Stores the head of the linked list
    Node* mainhead = nullptr;

    // Stores the head of linked lists of each row
    vector<Node*> head(m);
    Node *rightcurr, *newptr;

    // Create m linked lists by setting all 
    // the right nodes of every row
    for (int i = 0; i < m; i++) {
        head[i] = nullptr;

        for (int j = 0; j < n; j++) {
            newptr = new Node(mat[i][j]);

            // Assign the first node as the mainhead
            if (!mainhead) {
                mainhead = newptr;
            }

            // Set the head for the row or link 
            // the current node
            if (!head[i]) {
                head[i] = newptr;
            } 
            else {
                rightcurr->right = newptr;
            }

            rightcurr = newptr;
        }
    }

    // Set the down pointers for nodes in consecutive rows
    for (int i = 0; i < m - 1; i++) {
        Node *curr1 = head[i], *curr2 = head[i + 1];

        // Link corresponding nodes in consecutive rows
        while (curr1 && curr2) {
            curr1->down = curr2;
            curr1 = curr1->right;
            curr2 = curr2->right;
        }
    }

    // Return the mainhead of the constructed 
    // linked list
    return mainhead;
}

void printList(Node *head) {

    Node *currRow = head;
    while (currRow != nullptr) {
        Node *currCol = currRow;
        while (currCol != nullptr) {
            cout << currCol->data << " ";
            currCol = currCol->right;
        }
        cout << endl;
        currRow = currRow->down;
    }
}

